/* Resource metadata is generated by the local importer, never bundled. */
static HostSampleSpec sample_specs[4096];
static HostMusicSpec music_specs[256];
static char public_sample_paths[4096][256],public_music_paths[256][256];
static unsigned sample_spec_count,music_spec_count;
static int public_audio_map_load(void){
    FILE *f=fopen("data/audio-map.tsv","rb");if(!f)return 0;
    char line[512],path[256];unsigned a,b,c;float gain;int ok=1;
    while(fgets(line,sizeof(line),f)){
        if(line[0]=='S'&&sample_spec_count<4096&&sscanf(line,"S\t%u\t%u\t%f\t%255s",&a,&b,&gain,path)==4){
            if(strncmp(path,"data/audio/",11)||strstr(path,"..")||!isfinite(gain)||gain<0||gain>16){ok=0;break;}
            unsigned n=sample_spec_count++;strcpy(public_sample_paths[n],path);sample_specs[n]=(HostSampleSpec){a,b,public_sample_paths[n],gain};
        }else if(line[0]=='M'&&music_spec_count<256&&sscanf(line,"M\t%u\t%u\t%u\t%f\t%255s",&a,&b,&c,&gain,path)==5){
            if(strncmp(path,"data/audio/",11)||strstr(path,"..")||!isfinite(gain)||gain<0||gain>16){ok=0;break;}
            unsigned n=music_spec_count++;strcpy(public_music_paths[n],path);music_specs[n]=(HostMusicSpec){a,public_music_paths[n],b,c,gain};
        }else{ok=0;break;}
    }if(ferror(f))ok=0;fclose(f);return ok&&sample_spec_count&&music_spec_count;
}
